import java.util.*;

@GameTestHolder(UnusualCopper.MOD_ID)
@PrefixGameTestTemplate(false)
public final class EnchanterGameTests {
    static final ResourceLocation EFFICIENCY=new ResourceLocation("minecraft","efficiency");
    private static void loaded(GameTestHelper h,int id,java.util.function.Consumer<BlockPos> test){var p=new BlockPos(120008+id*128,70,120008);PopulationGameTests.loaded(h,new WorkArea(p.offset(-7,0,-7),p.offset(8,15,8)),()->test.accept(p));}
    static CopperMachineBlockEntity machine(ServerLevel level,BlockPos p){level.setBlock(p,Blocks.AIR.defaultBlockState(),3);level.setBlock(p,ModContent.MACHINES.get(MachineKind.ENCHANTMENT_RESONATOR).get().defaultBlockState(),3);var m=(CopperMachineBlockEntity)level.getBlockEntity(p);m.setOwner(UUID.randomUUID());m.energy.add(2_000_000,false);m.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_PICKAXE));m.inventory.setStackInSlot(1,new ItemStack(Items.LAPIS_LAZULI,64));return m;}
    static ServerPlayer owner(ServerLevel level,CopperMachineBlockEntity m,BlockPos p){var player=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(m.owner(),"CuEEnch"));player.setPos(p.getX()+.5,p.getY()+.5,p.getZ()+.5);xp(player,1000);return player;}
    static void xp(ServerPlayer player,int points){player.experienceLevel=0;player.experienceProgress=0;player.totalExperience=0;player.giveExperiencePoints(points);}
    static EnchanterMenu menu(CopperMachineBlockEntity m,ServerPlayer player){var menu=new EnchanterMenu(71,player.getInventory(),m);player.containerMenu=menu;return menu;}
    @GameTest(template="empty",timeoutTicks=200)
    public static void policyUsesRealMaximumAndRejectsConflictsTreasureAndWrongItems(GameTestHelper h){
        var pick=new ItemStack(Items.DIAMOND_PICKAXE);var offer=EnchantmentPolicy.offer(pick,EFFICIENCY);h.assertTrue(offer!=null&&offer.level()==Enchantments.BLOCK_EFFICIENCY.getMaxLevel()&&offer.xp()==188&&offer.cue()==125000,"Efficiency V quote uses actual maximum and configured real-point formula");
        h.assertTrue(EnchantmentPolicy.offer(pick,new ResourceLocation("minecraft","silk_touch"))!=null,"Silk touch is a suitable choice on a plain pickaxe");pick.enchant(Enchantments.BLOCK_FORTUNE,3);h.assertTrue(EnchantmentPolicy.offer(pick,new ResourceLocation("minecraft","silk_touch"))==null&&EnchantmentPolicy.offer(pick,new ResourceLocation("minecraft","fortune"))==null,"Fortune III blocks silk touch and reapplying its own maximum");
        h.assertTrue(EnchantmentPolicy.offer(new ItemStack(Items.DIRT),EFFICIENCY)==null&&EnchantmentPolicy.offer(new ItemStack(Items.DIAMOND_SWORD),EFFICIENCY)==null,"Unsuitable items cannot gain tool efficiency");
        var book=new ItemStack(Items.BOOK);h.assertTrue(EnchantmentPolicy.offer(book,new ResourceLocation("minecraft","mending"))==null&&EnchantmentPolicy.offer(book,new ResourceLocation("minecraft","binding_curse"))==null,"Treasure and curse are denied by default even on books");h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=300)
    public static void oneConfirmationPreservesNbtAndDebitsExactlyOnce(GameTestHelper h){loaded(h,0,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);var target=m.inventory.getStackInSlot(0);target.setHoverName(Component.literal("Copper keeper"));target.setDamageValue(31);target.getOrCreateTag().putString("CustomWitness","preserve");target.enchant(Enchantments.UNBREAKING,1);var original=target.copy();var menu=menu(m,player);
        h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player),"Owner requests a real server quote");var quote=menu.quote();h.assertTrue(quote.offer().xp()==235&&quote.offer().cue()==156250&&ItemStack.matches(original,m.inventory.getStackInSlot(0))&&m.inventory.getStackInSlot(1).getCount()==64,"Preview quotes the additional-enchantment price without changing anything");
        h.assertTrue(menu.confirm(m.runtimeIdentity,quote.nonce(),player),"Explicit nonce confirmation commits");var result=m.inventory.getStackInSlot(0);h.assertTrue(EnchantmentHelper.getItemEnchantmentLevel(Enchantments.BLOCK_EFFICIENCY,result)==5&&EnchantmentHelper.getItemEnchantmentLevel(Enchantments.UNBREAKING,result)==1&&result.getDamageValue()==31&&result.getHoverName().getString().equals("Copper keeper")&&result.getOrCreateTag().getString("CustomWitness").equals("preserve"),"Existing enchantments, name, damage and unrelated NBT survive");h.assertTrue(m.energy.stored()==1843750&&m.inventory.getStackInSlot(1).isEmpty()&&Math.abs(XpWallet.points(player)-765)<.0001,"Exactly 156250 CuE, 64 lapis and 235 real XP points are spent");h.assertTrue(!menu.confirm(m.runtimeIdentity,quote.nonce(),player)&&m.energy.stored()==1843750&&Math.abs(XpWallet.points(player)-765)<.0001,"Duplicate confirmation cannot spend again");
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void eachMissingCurrencyLeavesTargetAndOtherCurrenciesUntouched(GameTestHelper h){loaded(h,1,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);
        for(int missing=0;missing<3;missing++){xp(player,missing==0?187:1000);m.energy.restore(missing==2?124999:2000000);m.inventory.setStackInSlot(1,new ItemStack(Items.LAPIS_LAZULI,missing==1?63:64));var before=m.inventory.serializeNBT();var xp=XpWallet.capture(player);int energy=m.energy.stored();var menu=menu(m,player);h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player),"Quote remains visible without all resources");h.assertTrue(!menu.confirm(m.runtimeIdentity,menu.quote().nonce(),player)&&before.equals(m.inventory.serializeNBT())&&xp.matches(player)&&m.energy.stored()==energy,"A missing XP/lapis/CuE unit cannot partially charge another resource");}
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void identicalReplacementAndForeignContextInvalidateAQuote(GameTestHelper h){loaded(h,2,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);var menu=menu(m,player);menu.select(m.runtimeIdentity,EFFICIENCY,player);var quote=menu.quote();m.inventory.setStackInSlot(0,m.inventory.getStackInSlot(0).copy());h.assertTrue(!menu.confirm(m.runtimeIdentity,quote.nonce(),player)&&m.energy.stored()==2000000&&m.inventory.getStackInSlot(1).getCount()==64,"Even an identical replacement invalidates its old revision");
        menu=menu(m,player);h.assertTrue(!menu.select(UUID.randomUUID(),EFFICIENCY,player),"Wrong block runtime cannot request a quote");var foreign=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"EnchGuest"));foreign.setPos(player.position());var other=menu(m,foreign);h.assertTrue(!other.select(m.runtimeIdentity,EFFICIENCY,foreign),"Foreign player cannot prepare an operation");player.setPos(p.getX()+20,p.getY(),p.getZ());h.assertTrue(!menu(m,player).select(m.runtimeIdentity,EFFICIENCY,player),"Distant owner cannot prepare an operation");
    });}
    public static final class XpEvents {
        final UUID actor;final int mode;final CopperMachineBlockEntity machine;
        XpEvents(UUID actor,int mode,CopperMachineBlockEntity machine){this.actor=actor;this.mode=mode;this.machine=machine;}
        @SubscribeEvent public void xp(PlayerXpEvent.XpChange e){if(!e.getEntity().getUUID().equals(actor)||e.getAmount()>=0)return;if(mode==0)e.setCanceled(true);if(mode==1)e.setAmount(e.getAmount()+1);if(mode==4)machine.inventory.setStackInSlot(0,machine.inventory.getStackInSlot(0).copy());}
        @SubscribeEvent public void levels(PlayerXpEvent.LevelChange e){if(!e.getEntity().getUUID().equals(actor)||e.getLevels()>=0)return;if(mode==2)e.setCanceled(true);if(mode==3)e.setLevels(e.getLevels()+1);}
    }
    @GameTest(template="empty",timeoutTicks=300)
    public static void cancelledOrModifiedXpEventsCannotPartiallyCommit(GameTestHelper h){loaded(h,3,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);for(int mode=0;mode<5;mode++){var menu=menu(m,player);h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player),"Prepare a fresh exact quote");var q=menu.quote();var before=m.inventory.serializeNBT();var xp=XpWallet.capture(player);var events=new XpEvents(player.getUUID(),mode,m);MinecraftForge.EVENT_BUS.register(events);try{h.assertTrue(!menu.confirm(m.runtimeIdentity,q.nonce(),player)&&before.equals(m.inventory.serializeNBT())&&xp.matches(player)&&m.energy.stored()==2000000,"Cancelled/modified XP events or target replacement leave all fees untouched");}finally{MinecraftForge.EVENT_BUS.unregister(events);}}
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void lowerLevelUpgradeAndBookAdapterPreserveExistingMetadata(GameTestHelper h){loaded(h,4,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);var pick=m.inventory.getStackInSlot(0);pick.enchant(Enchantments.BLOCK_EFFICIENCY,2);pick.getEnchantmentTags().getCompound(0).putString("EnchantmentWitness","keep");var menu=menu(m,player);h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player)&&menu.confirm(m.runtimeIdentity,menu.quote().nonce(),player),"A lower existing level can upgrade to its real maximum");var result=m.inventory.getStackInSlot(0);h.assertTrue(result.getEnchantmentTags().size()==1&&result.getEnchantmentTags().getCompound(0).getString("EnchantmentWitness").equals("keep")&&EnchantmentHelper.getItemEnchantmentLevel(Enchantments.BLOCK_EFFICIENCY,result)==5,"Upgrade changes only that enchantment level without duplicate rows or lost row metadata");
        var book=new ItemStack(Items.BOOK);book.setHoverName(Component.literal("Resonant notebook"));book.getOrCreateTag().putString("BookWitness","keep");m.inventory.setStackInSlot(0,book);m.inventory.setStackInSlot(1,new ItemStack(Items.LAPIS_LAZULI,64));m.energy.restore(2000000);xp(player,1000);menu=menu(m,player);h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player)&&menu.confirm(m.runtimeIdentity,menu.quote().nonce(),player),"Standard book adapter applies an allowed maximum");result=m.inventory.getStackInSlot(0);h.assertTrue(result.is(Items.ENCHANTED_BOOK)&&EnchantmentHelper.getEnchantments(result).get(Enchantments.BLOCK_EFFICIENCY)==5&&result.getHoverName().getString().equals("Resonant notebook")&&result.getOrCreateTag().getString("BookWitness").equals("keep"),"Book conversion preserves full item tag and uses stored enchantments");
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void malformedAndHiddenBookEnchantmentsCannotBypassCompatibility(GameTestHelper h){
        var book=new ItemStack(Items.BOOK);var hidden=new ListTag();var row=new CompoundTag();row.putString("id","minecraft:fortune");row.putShort("lvl",(short)3);hidden.add(row);book.getOrCreateTag().put("StoredEnchantments",hidden);var original=book.copy();h.assertTrue(EnchantmentPolicy.offers(book).isEmpty()&&ItemStack.matches(book,original),"Plain-book hidden stored enchants cannot become a silk/fortune combination during conversion");
        var malformed=new ItemStack(Items.BOOK);var strings=new ListTag();strings.add(StringTag.valueOf("preserve malformed data"));malformed.getOrCreateTag().put("StoredEnchantments",strings);original=malformed.copy();h.assertTrue(EnchantmentPolicy.offers(malformed).isEmpty()&&ItemStack.matches(malformed,original),"Non-compound book enchantment data is refused without rewriting it");
        var pick=new ItemStack(Items.DIAMOND_PICKAXE);pick.enchant(Enchantments.BLOCK_FORTUNE,3);pick.enchant(Enchantments.SILK_TOUCH,1);h.assertTrue(EnchantmentPolicy.offers(pick).isEmpty(),"Already-conflicting input is not legitimized with another enchantment");pick=new ItemStack(Items.DIAMOND_PICKAXE);pick.enchant(Enchantments.BLOCK_EFFICIENCY,2);pick.enchant(Enchantments.BLOCK_EFFICIENCY,1);h.assertTrue(EnchantmentPolicy.offers(pick).isEmpty(),"Duplicate legacy enchantment rows are not silently rewritten");h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=300)
    public static void protectedTargetPortAndNbtSaveCannotAutomateAnEnchantment(GameTestHelper h){loaded(h,5,p->{var level=h.getLevel();var m=machine(level,p);var cap=m.getCapability(ForgeCapabilities.ITEM_HANDLER,Direction.UP).orElseThrow(()->new IllegalStateException("No fixture input port"));h.assertTrue(!cap.isItemValid(0,new ItemStack(Items.DIAMOND_PICKAXE))&&cap.insertItem(0,new ItemStack(Items.DIAMOND_PICKAXE),false).getCount()==1,"Automation cannot replace protected target");m.inventory.setStackInSlot(1,ItemStack.EMPTY);h.assertTrue(cap.insertItem(1,new ItemStack(Items.LAPIS_LAZULI,64),false).isEmpty(),"Automation can provide the exact lapis material");var player=owner(level,m,p);var menu=menu(m,player);menu.select(m.runtimeIdentity,EFFICIENCY,player);var q=menu.quote();var tag=m.saveWithFullMetadata();m.load(tag);h.assertTrue(!menu.confirm(m.runtimeIdentity,q.nonce(),player)&&m.energy.stored()==2000000&&m.inventory.getStackInSlot(1).getCount()==64,"Reload restores inventory/energy but invalidates an unpaid menu intent");h.assertTrue(!m.getUpdateTag().contains("Inventory")&&!m.getUpdateTag().contains("Owner"),"Protected target is never a public block update");
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void vanillaXpCurveAndFractionalBarAreSpentAsPoints(GameTestHelper h){loaded(h,6,p->{var level=h.getLevel();var m=machine(level,p);var player=owner(level,m,p);for(int l=0;l<100;l++){player.experienceLevel=l;h.assertTrue(XpWallet.span(l)==player.getXpNeededForNextLevel(),"XP span follows actual vanilla method at level "+l);}player.experienceLevel=20;player.experienceProgress=.35F;player.totalExperience=1000000;double before=XpWallet.points(player);var menu=menu(m,player);h.assertTrue(menu.select(m.runtimeIdentity,EFFICIENCY,player)&&menu.confirm(m.runtimeIdentity,menu.quote().nonce(),player),"Fractional bar state pays a real points price");h.assertTrue(Math.abs(before-XpWallet.points(player)-188)<.00001&&player.experienceLevel==16&&player.totalExperience==999812,"Spend preserves fractional bar and does not mistake the historical total for a wallet");
        m.inventory.setStackInSlot(0,new ItemStack(Items.DIAMOND_PICKAXE));m.inventory.setStackInSlot(1,new ItemStack(Items.LAPIS_LAZULI,64));m.energy.restore(2000000);player.experienceLevel=0;player.experienceProgress=0;player.totalExperience=1000000;menu=menu(m,player);menu.select(m.runtimeIdentity,EFFICIENCY,player);h.assertTrue(!menu.confirm(m.runtimeIdentity,menu.quote().nonce(),player)&&player.totalExperience==1000000&&m.energy.stored()==2000000,"Historical XP alone cannot fund an enchantment");
    });}
    @GameTest(template="empty",timeoutTicks=800)
    public static void unpaidQuoteExpiresWithoutSpending(GameTestHelper h){var p=new BlockPos(121032,70,120008);var state=new Object(){CopperMachineBlockEntity m;ServerPlayer player;EnchanterMenu menu;UUID nonce;};PopulationGameTests.loadedSequence(h,new WorkArea(p.offset(-7,0,-7),p.offset(8,15,8)),seq->seq.thenExecute(()->{state.m=machine(h.getLevel(),p);state.player=owner(h.getLevel(),state.m,p);state.menu=menu(state.m,state.player);h.assertTrue(state.menu.select(state.m.runtimeIdentity,EFFICIENCY,state.player),"Create a real timed unpaid intent");state.nonce=state.menu.quote().nonce();}).thenIdle(EnchanterMenu.QUOTE_TICKS+1).thenExecute(()->h.assertTrue(!state.menu.confirm(state.m.runtimeIdentity,state.nonce,state.player)&&state.m.energy.stored()==2000000&&state.m.inventory.getStackInSlot(1).getCount()==64&&Math.abs(XpWallet.points(state.player)-1000)<.0001,"Expired intent never consumes a resource")));}
}
